//! Synthetic 500-entry KDBX 4.0 fixture (M3-03/M3-04/M5-03/G3 prerequisite).
//!
//! The committed file is `tests/fixtures/synthetic/synthetic-500.kdbx`
//! (master password `demopass`, registered in `tests/fixtures/manifest.json`).
//! It is generated by the ignored test below through the project's own writer
//! (`keepassity_core::kdbx::writer::write_model`, i.e. the keepassxcr backend
//! used by the app's save path), so it is a real KDBX 4.0 Argon2id database and
//! not a hand-crafted XML blob.
//!
//! Regenerate (from the repository root):
//!
//! ```text
//! $env:KEEPASSITY_SYNTHETIC_OUT = (Resolve-Path tests/fixtures/synthetic).Path
//! cargo test -p keepassity-core --test synthetic_fixture generate_synthetic_500 -- --ignored --nocapture
//! pwsh -File tools/fixture-gen/regenerate.ps1 -SkipGenerate
//! ```
//!
//! The generator draws a fresh KDF salt, master seed and IV on every run, so the
//! bytes (and therefore the manifest SHA-256) change every time. The manifest
//! must be refreshed together with the file; `verify-fixtures.ps1` fails
//! otherwise.
//!
//! Every value here is synthetic test data: the master password, the entry
//! passwords and the TOTP seeds are public constants with no real-world use.

use keepassity_core::model::{
    Database, DeletedObject, Entry, Group, Meta, StringField, Times, Uuid,
};
use keepassity_core::totp::fields as totp_fields;
use std::path::{Path, PathBuf};

/// Public test password recorded in `tests/fixtures/README.md`.
pub const MASTER_PASSWORD: &str = "demopass";
/// File name inside `tests/fixtures/synthetic/`.
pub const FILE_NAME: &str = "synthetic-500.kdbx";
/// Required entry count (the G3 scroll check needs 500 rows).
pub const ENTRY_COUNT: u64 = 500;

const GROUP_NAMES: [&str; 6] = ["Personal", "Work", "Banking", "Social", "Email", "TOTP"];
const TOPICS: [&str; 10] = [
    "Personal",
    "Work",
    "Banking",
    "Social",
    "Email",
    "Shopping",
    "Streaming",
    "Development",
    "Server",
    "Travel",
];
const NON_ASCII_TITLE_PREFIXES: [&str; 4] = ["条目", "Übergang", "サンプル", "пример"];
const NON_ASCII_USER_PREFIXES: [&str; 3] = ["用户", "пользователь", "ユーザー"];

/// Every 25th entry (20 of 500) gets a public `otp` (otpauth) field.
const TOTP_EVERY: u64 = 25;
/// Every 13th entry (39 of 500) gets a non-ASCII title.
const NON_ASCII_TITLE_EVERY: u64 = 13;
/// Every 17th entry (30 of 500) gets a non-ASCII username.
const NON_ASCII_USER_EVERY: u64 = 17;
/// Every 11th entry (46 of 500) gets a percent-encoded non-ASCII URL path.
const ENCODED_URL_EVERY: u64 = 11;
/// Every 10th entry (50 of 500) carries a custom `Recovery` field.
const RECOVERY_EVERY: u64 = 10;
/// Every 50th entry (10 of 500) has one history entry.
const HISTORY_EVERY: u64 = 50;
/// Tombstones written into `DeletedObjects`.
const DELETED_OBJECT_COUNT: u64 = 3;

fn repository_tests_fixtures() -> PathBuf {
    // crates/core/tests -> crates/core -> crates -> <repo>
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures")
        .join("synthetic")
}

fn committed_fixture_path() -> PathBuf {
    repository_tests_fixtures().join(FILE_NAME)
}

fn tagged_uuid(namespace: u8, index: u64) -> Uuid {
    let mut bytes = [0u8; 16];
    bytes[0] = namespace;
    bytes[1] = 0x4b; // "K" marker, keeps synthetic UUIDs recognisable
    bytes[2..10].copy_from_slice(&index.to_be_bytes());
    bytes[15] = 1;
    Uuid::from_bytes(bytes)
}

fn times_for(index: u64) -> Times {
    let minute = index % 60;
    let stamp = format!("2026-01-01T00:{minute:02}:00Z");
    Times {
        creation: "2026-01-01T00:00:00Z".to_string(),
        last_modification: stamp.clone(),
        last_access: stamp,
        expiry: "2026-01-01T00:00:00Z".to_string(),
        expires: false,
        usage_count: index % 5,
        location_changed: "2026-01-01T00:00:00Z".to_string(),
        unknown: Vec::new(),
    }
}

fn string_field(key: &str, value: impl Into<String>, protected: bool) -> StringField {
    StringField {
        key: key.to_string(),
        value: value.into(),
        protected,
        unknown: Vec::new(),
    }
}

fn synthetic_entry(index: u64) -> Entry {
    let topic = TOPICS[(index as usize) % TOPICS.len()];
    let title = if index.is_multiple_of(NON_ASCII_TITLE_EVERY) {
        let prefix = NON_ASCII_TITLE_PREFIXES
            [((index / NON_ASCII_TITLE_EVERY) as usize) % NON_ASCII_TITLE_PREFIXES.len()];
        format!("Synthetic {prefix} {index:03} {topic}")
    } else {
        format!("Synthetic Entry {index:03} {topic}")
    };
    let username = if index.is_multiple_of(NON_ASCII_USER_EVERY) {
        let prefix = NON_ASCII_USER_PREFIXES
            [((index / NON_ASCII_USER_EVERY) as usize) % NON_ASCII_USER_PREFIXES.len()];
        format!("{prefix} {index:04}")
    } else {
        format!("user{index:04}")
    };
    let url = if index.is_multiple_of(ENCODED_URL_EVERY) {
        // percent-encoded non-ASCII path ("账户" = %E8%B4%A6%E6%88%B7)
        format!("https://example.com/%E8%B4%A6%E6%88%B7/{index:04}")
    } else {
        format!("https://example.com/account/{index:04}")
    };
    let notes = format!(
        "Synthetic note {index:04}. Search keyword keyword-{index:04}. \
         Generated test data, not a real account."
    );

    let mut entry = Entry {
        uuid: tagged_uuid(0xe1, index),
        icon_id: (index % 48) as u32,
        times: times_for(index),
        tags: vec![topic.to_ascii_lowercase()],
        ..Entry::default()
    };
    entry.strings.push(string_field("Title", title, false));
    entry
        .strings
        .push(string_field("UserName", username, false));
    entry.strings.push(string_field(
        "Password",
        format!("synthetic-{index:04}-pw"),
        true,
    ));
    entry.strings.push(string_field("URL", url, false));
    entry.strings.push(string_field("Notes", notes, false));

    if index.is_multiple_of(RECOVERY_EVERY) {
        entry.strings.push(string_field(
            "Recovery",
            format!("recovery-{index:04}"),
            false,
        ));
    }
    if index.is_multiple_of(TOTP_EVERY) {
        // Public synthetic secret; never a real TOTP seed.
        entry.strings.push(string_field(
            "otp",
            format!(
                "otpauth://totp/Synthetic:{index:04}?secret=JBSWY3DPEHPK3PXP&issuer=Synthetic&period=30&digits=6"
            ),
            false,
        ));
    }
    if index.is_multiple_of(HISTORY_EVERY) {
        let mut previous = entry.clone();
        previous.strings.retain(|field| field.key != "Title");
        previous.strings.push(string_field(
            "Title",
            format!("Synthetic Entry {index:03} (previous)"),
            false,
        ));
        previous.times.last_modification = "2025-12-31T23:59:00Z".to_string();
        entry.history.push(previous);
    }
    entry
}

/// Build the deterministic-shape (fresh-crypto) 500-entry database model.
pub fn synthetic_database() -> Database {
    let mut root = Group {
        uuid: tagged_uuid(0x9a, 0),
        name: "Synthetic 500".to_string(),
        times: times_for(0),
        is_expanded: true,
        ..Group::default()
    };
    let mut buckets: Vec<Vec<Entry>> = (0..GROUP_NAMES.len()).map(|_| Vec::new()).collect();
    for index in 0..ENTRY_COUNT {
        buckets[(index % GROUP_NAMES.len() as u64) as usize].push(synthetic_entry(index));
    }
    for (position, name) in GROUP_NAMES.iter().enumerate() {
        root.groups.push(Group {
            uuid: tagged_uuid(0x9b, position as u64),
            name: (*name).to_string(),
            times: times_for(position as u64),
            is_expanded: true,
            entries: std::mem::take(&mut buckets[position]),
            ..Group::default()
        });
    }
    let deleted_objects = (0..DELETED_OBJECT_COUNT)
        .map(|index| DeletedObject {
            uuid: tagged_uuid(0xde, index),
            deletion_time: "2025-12-30T12:00:00Z".to_string(),
        })
        .collect();
    Database {
        format_version: "4.0".to_string(),
        outer: None,
        meta: Meta {
            database_name: "Synthetic 500".to_string(),
            database_description: "Synthetic 500-entry fixture generated by \
                 crates/core/tests/synthetic_fixture.rs; master password demopass; \
                 contains no real secrets."
                .to_string(),
            history_max_items: 10,
            history_max_size: 6 * 1024 * 1024,
            ..Meta::default()
        },
        root,
        deleted_objects,
        unknown: Vec::new(),
        raw_xml: None,
        raw_xml_sha256: None,
    }
}

/// Number of indices in `0..count` that are multiples of `step` (index 0 counts).
fn every_nth(count: u64, step: u64) -> usize {
    ((count - 1) / step + 1) as usize
}

fn flatten_entries<'a>(group: &'a Group, out: &mut Vec<&'a Entry>) {
    out.extend(group.entries.iter());
    for child in &group.groups {
        flatten_entries(child, out);
    }
}

fn count_groups(group: &Group) -> usize {
    1 + group.groups.iter().map(count_groups).sum::<usize>()
}

fn all_entries(database: &Database) -> Vec<&Entry> {
    let mut out = Vec::new();
    flatten_entries(&database.root, &mut out);
    out
}

#[test]
#[ignore = "regenerates the committed fixture; run explicitly when the fixture definition changes"]
fn generate_synthetic_500() {
    let output_directory = std::env::var_os("KEEPASSITY_SYNTHETIC_OUT")
        .map(PathBuf::from)
        .unwrap_or_else(repository_tests_fixtures);
    std::fs::create_dir_all(&output_directory).expect("create synthetic fixture directory");

    let database = synthetic_database();
    let expected_entries: usize = ENTRY_COUNT as usize;
    assert_eq!(all_entries(&database).len(), expected_entries);
    assert_eq!(count_groups(&database.root), GROUP_NAMES.len() + 1);

    let bytes = keepassity_core::kdbx::writer::write_model(&database, MASTER_PASSWORD)
        .expect("write_model");
    let output_path = output_directory.join(FILE_NAME);
    std::fs::write(&output_path, &bytes).expect("write fixture file");

    // Read the bytes back with the independent reader before declaring success.
    let reopened = keepassity_core::kdbx::reader::parse(&bytes, MASTER_PASSWORD)
        .expect("generated fixture must be readable");
    let reopened_entries = all_entries(&reopened);
    assert_eq!(reopened_entries.len(), expected_entries);
    assert_eq!(reopened.format_version, "4.0");
    println!(
        "wrote {} ({} bytes, {} entries, {} groups)",
        output_path.display(),
        bytes.len(),
        reopened_entries.len(),
        count_groups(&reopened.root)
    );
    println!(
        "next: refresh tests/fixtures/manifest.json (use tools/fixture-gen/regenerate.ps1 -SkipGenerate)"
    );
}

#[test]
fn committed_fixture_has_the_documented_shape() {
    let path = committed_fixture_path();
    let bytes = std::fs::read(&path).unwrap_or_else(|error| {
        panic!(
            "cannot read {}: {error}\n\
             Regenerate it with: cargo test -p keepassity-core --test synthetic_fixture \
             generate_synthetic_500 -- --ignored",
            path.display()
        )
    });
    assert!(
        bytes.len() > 10_000,
        "500-entry encrypted database should be at least 10 KB, got {} bytes",
        bytes.len()
    );
    let database = keepassity_core::kdbx::reader::parse(&bytes, MASTER_PASSWORD)
        .expect("fixture must decrypt with the documented password");
    assert_eq!(database.format_version, "4.0");
    assert_eq!(database.meta.database_name, "Synthetic 500");
    assert_eq!(count_groups(&database.root), GROUP_NAMES.len() + 1);
    assert_eq!(
        database.deleted_objects.len(),
        DELETED_OBJECT_COUNT as usize
    );

    let entries = all_entries(&database);
    assert_eq!(entries.len(), ENTRY_COUNT as usize);
    for entry in &entries {
        for field in ["Title", "UserName", "Password", "URL", "Notes"] {
            assert!(
                entry.field(field).is_some_and(|value| !value.is_empty()),
                "every synthetic entry must have a non-empty {field} field"
            );
        }
    }

    let totp_entries: Vec<&Entry> = entries.iter().copied().filter(|e| e.has_totp()).collect();
    assert_eq!(
        totp_entries.len(),
        every_nth(ENTRY_COUNT, TOTP_EVERY),
        "documented TOTP entry count"
    );
    for entry in &totp_entries {
        let read = totp_fields::read_entry(entry)
            .expect("synthetic otpauth URI must parse")
            .expect("entry must expose a TOTP configuration");
        assert_eq!(read.spec.config.digits, 6);
        assert_eq!(read.spec.issuer.as_deref(), Some("Synthetic"));
    }

    let non_ascii_titles = entries
        .iter()
        .filter(|entry| entry.field("Title").is_some_and(|title| !title.is_ascii()))
        .count();
    assert_eq!(
        non_ascii_titles,
        every_nth(ENTRY_COUNT, NON_ASCII_TITLE_EVERY)
    );
    let non_ascii_usernames = entries
        .iter()
        .filter(|entry| {
            entry
                .field("UserName")
                .is_some_and(|username| !username.is_ascii())
        })
        .count();
    assert_eq!(
        non_ascii_usernames,
        every_nth(ENTRY_COUNT, NON_ASCII_USER_EVERY)
    );
    let encoded_urls = entries
        .iter()
        .filter(|entry| {
            entry
                .field("URL")
                .is_some_and(|url| url.contains("%E8%B4%A6%E6%88%B7"))
        })
        .count();
    assert_eq!(encoded_urls, every_nth(ENTRY_COUNT, ENCODED_URL_EVERY));

    let recovery_fields = entries
        .iter()
        .filter(|entry| entry.field("Recovery").is_some())
        .count();
    assert_eq!(recovery_fields, every_nth(ENTRY_COUNT, RECOVERY_EVERY));
    let history_entries: usize = entries.iter().map(|entry| entry.history.len()).sum();
    assert_eq!(history_entries, every_nth(ENTRY_COUNT, HISTORY_EVERY));

    // Search-shape invariants used by the perf evidence and the drills.
    let keyword_hits = entries
        .iter()
        .filter(|entry| {
            entry
                .field("Notes")
                .is_some_and(|notes| notes.contains("keyword-0042"))
        })
        .count();
    assert_eq!(keyword_hits, 1);
    let all_titles_contain_prefix = entries
        .iter()
        .filter(|entry| {
            entry
                .field("Title")
                .is_some_and(|title| title.starts_with("Synthetic "))
        })
        .count();
    assert_eq!(all_titles_contain_prefix, ENTRY_COUNT as usize);

    // Wrong password must be rejected (fixture is a real encrypted database).
    assert!(
        keepassity_core::kdbx::reader::parse(&bytes, "wrong-password").is_err(),
        "fixture must not open with a wrong password"
    );
}
